75| impl HookEntry {
76|     /// Whether this entry applies to `tool_name`.
77|     ///
78|     /// The harness treats a matcher as a regex over the tool name, so this
79|     /// does too, anchored so `Edit` cannot match `MultiEdit` by accident. A
80|     /// pattern that will not compile falls back to exact equality — a
81|     /// declaration clud cannot understand should under-match, never
82|     /// over-match, since over-matching would fire someone's guard against
83|     /// tools they never meant to guard.
84|     #[must_use]
85|     pub fn matches_tool(&self, tool_name: Option<&str>) -> bool {
86|         let Some(matcher) = self.matcher.as_deref() else {
87|             return true;
88|         };
89|         let matcher = matcher.trim();
90|         if matcher.is_empty() || matcher == MATCH_ALL {
91|             return true;
92|         }
93|         let Some(tool_name) = tool_name else {
94|             // A tool-scoped matcher on an event that carries no tool cannot
95|             // be satisfied; skip rather than guess.
96|             return false;
97|         };
98|         match regex::Regex::new(&format!("^(?:{matcher})$")) {
99|             Ok(regex) => regex.is_match(tool_name),
100|             Err(_) => matcher == tool_name,
101|         }
102|     }
103| }
